/// <summary>
/// Add button for DMS connection.
/// </summary>
public class AVADAIFormRunController
{
    private FormRun                     formRun;
    private AVADAIArchiveFormConfig     archiveFormConfig;


}

Method.Source:
/// <summary>
/// Returns a AVADAIFormRunController.
/// </summary>
/// <param name = "_formRun">The form run.</param>
/// <returns>A new <c>AVADAIFormRunController</c> object.</returns>
public static AVADAIFormRunController construct(FormRun _formRun)
{
    if (_formRun == null)
    {
        throw error("@AVADAI:FormRunMissing");
    }

    AVADAIFormRunController avaFormRunController = new AVADAIFormRunController();
    avaFormRunController.parmFormRun(_formRun);
    avaFormRunController.parmArchiveFormConfig(AVADAIArchiveFormConfig::findForm(_formRun.name()));
    return avaFormRunController;
}

/// <summary>
/// Set form configuration.
/// </summary>
/// <param name = "AVADAIArchiveFormConfig">The configuration.</param>
/// <returns>A <c>AVADAIArchiveFormConfig</c> object.</returns>
public AVADAIArchiveFormConfig parmArchiveFormConfig(AVADAIArchiveFormConfig _archiveFormConfig)
{
    if (_archiveFormConfig != null)
    {
        archiveFormConfig = _archiveFormConfig;
    }

    return archiveFormConfig;
}

/// <summary>
/// Returns a formrun.
/// </summary>
/// <param name = "_formRun">The form run.</param>
/// <returns>A <c>FormRun</c> object.</returns>
public FormRun parmFormRun(FormRun _formRun)
{
    if (_formRun != null)
    {
        formRun = _formRun;
    }

    return formRun;
}

/// <summary>
/// Add DMS connection Button.
/// </summary>
public void addDMSButtonGroupAndButton()
{
    FormButtonGroupControl buttonGroupCtrl = this.findOrCreateButtonGroup(formRun.design());
    buttonGroupCtrl.caption("@AVADAI:DAIGroup");
    buttonGroupCtrl.heightMode(FormWidth::Auto);
    buttonGroupCtrl.widthMode(FormWidth::Auto);
    buttonGroupCtrl.arrangeMethod(FormArrangeMethod::Vertical);

    if (buttonGroupCtrl)
    {
        if (buttonGroupCtrl.dataSource() == 0)
        {
            if (formRun.defaultDataSource())
            {
                buttonGroupCtrl.dataSource(formRun.defaultDataSource().id());
            }
            else if (formRun.dataSource())
            {
                buttonGroupCtrl.dataSource(formRun.dataSource().id());
            }
        }
        this.addMenuFunctionButton(buttonGroupCtrl, MenuItemType::Action, MenuItemActionStr(AVADAIOpenArchiveUrl), "@AVADAI:OpenArchive", "@AVADAI:OpenArchiveHelp");
    }
}

/// <summary>
/// Add menu action button.
/// </summary>
/// <param name = "_buttonGroupCtrl">The button group.</param>
/// <param name = "_menuItemType">.</param>
/// <param name = "_menuItem">The menu item.</param>
/// <param name = "_text">The text.</param>
/// <param name = "_helpText">The help text.</param>
protected void addMenuFunctionButton(
                                    FormButtonGroupControl  _buttonGroupCtrl,
                                    MenuItemType            _menuItemType,
                                    str                     _menuItem,
                                    str                     _text,
                                    str                     _helpText='')
{
    FormFunctionButtonControl	menuButton;

    if (_buttonGroupCtrl != null)
    {
        menuButton = _buttonGroupCtrl.addControl(FormControlType::MenuFunctionButton, _text);
        menuButton.menuItemType(_menuItemType);
        menuButton.menuItemName(_menuItem);
        menuButton.helpText(_helpText); 
        menuButton.dataSource(archiveFormConfig.DatasourceName);
    }
}

/// <summary>
/// Returns a Groupcontrol.
/// </summary>
/// <param name = "_design">FormDesign</param>
/// <returns>A new <c>FormButtonGroupControl</c> object.</returns>
protected FormButtonGroupControl findOrCreateButtonGroup(FormDesign _design)
{
    FormActionPaneControl       actionPane;
    FormActionPaneTabControl    tabCtrl;
    FormButtonGroupControl      buttonGroupCtrl;
    FormGroupControl            filterGroupCtrl;
    int							i = 1;

    actionPane = this.findActionPane(_design);
    if (actionPane)
    {
        if (actionPane.controlCount() > 0)
        {
            while (tabCtrl == null && i < actionPane.controlCount())
            {
                if (actionPane.controlNum(i).type() == FormControlType::ActionPaneTab)
                {
                    tabCtrl = actionPane.controlNum(i);
                }
                i++;
            }
        }
        else
        {
            tabCtrl     = actionPane.addControl(FormControlType::ActionPaneTab, identifierStr(AVADAIActionPane));
        }
        buttonGroupCtrl = tabCtrl.addControl(FormControlType::ButtonGroup, identifierstr(AVADAIGroup));
    }

    if (buttonGroupCtrl == null)
    {
        filterGroupCtrl = formRun.design().addControl(FormControlType::Group, identifierstr(AVADAIPane), null);
        buttonGroupCtrl = filterGroupCtrl.addControl(FormControlType::ButtonGroup, identifierstr(AVADAIGroup));
    }

    return buttonGroupCtrl;
}

/// <summary>
/// Returns a formActionPaneControl.
/// </summary>
/// <param name = "_curControlObj">Control</param>
/// <returns>A new <c>FormActionPaneControl</c> object.</returns>
protected FormActionPaneControl findActionPane(Object _curControlObj)
{
    int                     ctrlCount;
    int                     i;
    object                  controlObj;

    ctrlCount = _curControlObj.controlCount();
    for (i = 1; i <= ctrlCount; i++)
    {
        controlObj = _curControlObj.controlNum(i);

        if (controlObj && controlObj is FormActionPaneControl)
        {
            return controlObj;
        }
    }
    for (i = 1; i <= ctrlCount; i++)
    {
        controlObj = _curControlObj.controlNum(i);

        if (controlObj)
        {
            if (controlObj is FormGroupControl  ||
                controlObj is FormTabControl    ||
                controlObj is FormTabPageControl)
            {
                controlObj = this.findActionPane(controlObj);
                if (controlObj)
                {
                    return controlObj;
                }
            }
        }
    }

    return null;
}
